import test from "node:test"
import assert from "node:assert/strict"
import { readFileSync } from "node:fs"
import { createDeviceStore, accountKey, guestKey } from "../lib/device-progress"
import { restoreCloudCopy } from "../lib/cloud-copy"
import { freshProgress } from "../lib/progress"

// Exported by b11c119 from an isolated guest browser, not generated by the current schema.
const shipped = readFileSync(
  new URL("./fixtures/shipped-v1.json", import.meta.url),
  "utf8"
).trim()

function setup() {
  const files = new Map<string, string>()
  const storage = {
    getItem: (key: string) => files.get(key) ?? null,
    setItem: (key: string, value: string) => {
      files.set(key, value)
    },
  }
  return { files, storage, store: createDeviceStore(() => storage) }
}

test("both v1 storage namespaces reopen a shipped save without rewriting it", () => {
  const { files, store } = setup()
  for (const key of [guestKey, accountKey("fixture")]) {
    files.set(key, shipped)
    store.select(key)
    assert.deepEqual(store.getSnapshot().progress, JSON.parse(shipped))
    assert.equal(store.exportFile(key), shipped)
    assert.equal(
      store.update(key, (p) => ({ ...p, speechRate: 1 })),
      true
    )
    const saved = JSON.parse(files.get(key)!)
    assert.deepEqual(saved, {
      ...JSON.parse(shipped),
      speechRate: 1,
      updated: saved.updated,
    })
    assert.ok(saved.updated > 0)
  }
})

test("corrupt, invalid and zero-length saves are read-only and export byte-for-byte", () => {
  const { files, store } = setup()
  for (const original of ["{lost", '{"schema":2}', ""]) {
    files.set(guestKey, original)
    store.select(guestKey)
    assert.equal(
      store.update(guestKey, () => freshProgress()),
      false
    )
    assert.equal(store.exportFile(guestKey), original)
    assert.equal(store.replace(guestKey, freshProgress()), true)
    assert.equal(store.getSnapshot().readOnly, false)
  }
})

test("stale tabs and account callbacks cannot overwrite another save; quota failures can retry", () => {
  const { files, store, storage } = setup()
  store.select(guestKey)
  files.set(guestKey, shipped)
  assert.equal(
    store.update(guestKey, () => freshProgress()),
    false
  )
  assert.equal(files.get(guestKey), shipped)
  const setItem = storage.setItem
  storage.setItem = () => {
    throw new Error("Storage full")
  }
  assert.equal(
    store.update(guestKey, (p) => ({ ...p, level: 7 })),
    false
  )
  assert.equal(store.getSnapshot().progress.level, 4)
  storage.setItem = setItem
  assert.equal(
    store.update(guestKey, (p) => ({ ...p, level: 7 })),
    true
  )
  store.select(accountKey("learner"))
  assert.equal(store.replace(guestKey, freshProgress()), false)
  assert.throws(() => store.exportFile(guestKey), /profile changed/)
  assert.equal(files.has(accountKey("learner")), false)
})

test("an absent or malformed cloud copy never replaces local study, and a failed write is not a sync", () => {
  const { files, store } = setup()
  const key = accountKey("learner")
  files.set(key, shipped)
  store.select(key)
  const write = (p: ReturnType<typeof freshProgress>) => store.replace(key, p)
  for (const value of [
    { progress: null, version: 0 },
    { version: 3 },
    { progress: freshProgress(), version: -1 },
    { progress: { level: 9 }, version: 1 },
  ]) {
    assert.throws(
      () => restoreCloudCopy(value, write),
      /no cloud copy|incompatible/
    )
    assert.equal(files.get(key), shipped)
  }
  const remote = { version: 2, progress: { ...freshProgress(), level: 8 } }
  assert.throws(
    () => restoreCloudCopy(remote, () => false),
    /could not be saved/
  )
  assert.equal(restoreCloudCopy(remote, write), 2)
  assert.equal(store.getSnapshot().progress.level, 8)
})
